import {ClaimCustomizationSection} from './ClaimCustomizationSection'
import {Checkbox, FormControl} from '@primer/react'
import type {IssuerClaimPayload} from '../types'
import {useOIDCConfigurationMutation} from '../hooks/use-oidc-configuration-mutation'
import {useState} from 'react'
import {useBannerContext} from '../context/BannerProvider'

type Props = {
  includeEnterpriseSlugInIssuer?: boolean
}

export function IssuerClaimCustomization({includeEnterpriseSlugInIssuer: initialIncludeEnterpriseSlugInIssuer}: Props) {
  const [includeEnterpriseSlugInIssuer, setIncludeEnterpriseSlugInIssuer] = useState(
    !!initialIncludeEnterpriseSlugInIssuer,
  )
  const {setBanner} = useBannerContext()

  const {isPending: isSaving, mutate: saveIssuerClaim} = useOIDCConfigurationMutation<IssuerClaimPayload>({
    pathSuffix: 'issuer-claim',
    onSuccess: () => {
      setBanner({message: 'Issuer claim configuration saved successfully.', type: 'success'})
    },
  })

  return (
    <ClaimCustomizationSection
      title="Issuer claim"
      subtitle="Customize the issuer (iss) claim in the OIDC token, used to identify the token provider."
      onSave={() => saveIssuerClaim({includeEnterpriseSlugInIssuer})}
      isSaving={isSaving}
    >
      <FormControl>
        <Checkbox
          checked={includeEnterpriseSlugInIssuer}
          onChange={e => setIncludeEnterpriseSlugInIssuer(e.target.checked)}
        />
        <FormControl.Label>Use enterprise-specific issuer URL</FormControl.Label>
        <FormControl.Caption>
          When enabled, the issuer URL will include your enterprise&apos;s slug.
        </FormControl.Caption>
      </FormControl>
    </ClaimCustomizationSection>
  )
}
