import {MultiSelectPickerAnchor} from '@github-ui/filter-picker'

import type {MultiSelectPropertiesProps, PickerProperty} from './types'
import {MultiSelectPropertiesPickerDialog} from './MultiSelectPropertiesPickerDialog'
import {usePropertyItemConfig} from './ItemConfig'

export function MultiSelectPropertiesPicker<TItem extends PickerProperty>(props: MultiSelectPropertiesProps<TItem>) {
  const {['aria-describedby']: ariaDescribedby, ...dialogProps} = props
  const itemConfig = usePropertyItemConfig()

  return (
    <MultiSelectPickerAnchor<TItem>
      aria-describedby={ariaDescribedby}
      isOpenInitially={false}
      itemConfig={itemConfig}
      selected={dialogProps.selected}
      renderDialog={publicProps => <MultiSelectPropertiesPickerDialog {...publicProps} {...dialogProps} />}
    />
  )
}
