import {ControlGroup} from '@github-ui/control-group'
import {ClaimCustomizationSection} from './ClaimCustomizationSection'
import {MultiSelectPropertiesPicker} from './properties-picker/MultiSelectPropertiesPicker'
import type {CustomPropertyInclusionsPayload, CustomPropertyItem, SettingsSource} from '../types'
import {useState} from 'react'
import {useOIDCConfigurationMutation} from '../hooks/use-oidc-configuration-mutation'
import {useBannerContext} from '../context/BannerProvider'

type Props = {
  includedProperties?: CustomPropertyItem[]
  source?: SettingsSource
}

export function CustomPropertyInclusions({includedProperties: initialIncludedProperties, source}: Props) {
  const [includedProperties, setIncludedProperties] = useState(initialIncludedProperties ?? [])
  const {setBanner} = useBannerContext()

  const {isPending: isSaving, mutate: saveCustomPropertyClaims} =
    useOIDCConfigurationMutation<CustomPropertyInclusionsPayload>({
      pathSuffix: 'custom-property-claims',
      onSuccess: () => {
        setBanner({message: 'Custom property claims configuration saved successfully.', type: 'success'})
      },
    })

  return (
    <ClaimCustomizationSection
      className="tmp-p-3"
      title="Custom property claims"
      subtitle="Specify which custom properties should be included as claims in the OIDC token."
      onSave={() => {
        const includedPropertyNames = includedProperties.map(property => property.propertyName)
        saveCustomPropertyClaims({includedProperties: includedPropertyNames})
      }}
      isSaving={isSaving}
    >
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default">Select custom properties for inclusion</ControlGroup.Title>
        <ControlGroup.Description id="custom-property-inclusions">
          Manage the included custom properties.
        </ControlGroup.Description>
        <ControlGroup.Custom>
          <MultiSelectPropertiesPicker
            selected={includedProperties}
            onSubmit={setIncludedProperties}
            aria-describedby="custom-property-inclusions"
            source={source}
          />
        </ControlGroup.Custom>
      </ControlGroup.Item>
    </ClaimCustomizationSection>
  )
}
