import {createContext, type RefObject, use, useMemo, useRef, useState} from 'react'

interface BannerAction {
  type: 'success' | 'critical'
  message: string
}

interface BannerContextState {
  banner: BannerAction | null
  bannerRef: RefObject<HTMLElement | null> | null
  setBanner: (banner: BannerAction | null) => void
}

export const BannerContext = createContext<BannerContextState | null>(null)

export function BannerProvider({children}: React.PropsWithChildren) {
  const [banner, setBanner] = useState<BannerAction | null>(null)
  const bannerRef = useRef<HTMLElement>(null)

  const state = useMemo<BannerContextState>(() => ({banner, setBanner, bannerRef}), [banner, setBanner, bannerRef])

  return <BannerContext value={state}>{children}</BannerContext>
}

export function useBannerContext() {
  const context = use(BannerContext)

  if (!context) throw new Error('useBannerContext must be used within BannerProvider')

  return context
}
