import {Outlet} from '@github-ui/react-router'
import {BannerProvider, useBannerContext} from '../context/BannerProvider'
import {Banner} from '@primer/react'
import {OidcConfigurationHeader} from '../components/OidcConfigurationHeader'

export function LayoutRoute() {
  return (
    <BannerProvider>
      <PageBanner />
      <OidcConfigurationHeader />
      <Outlet />
    </BannerProvider>
  )
}

function PageBanner() {
  const {banner, setBanner, bannerRef} = useBannerContext()

  if (!banner) return null
  return (
    <Banner
      ref={bannerRef}
      className="pr-mb-3"
      title="OIDC configuration update information"
      variant={banner.type}
      onDismiss={() => setBanner(null)}
      hideTitle
      description={banner.message}
    />
  )
}
