import {mainQuery} from '@github-ui/react-core/future/main-query'
import {actionsOidcConfigurationAppBuilder} from '../config/app-builder'
import type {CustomPropertyItem, SettingsSource} from '../types'

export type OrganizationOidcConfigurationResponse = {
  subjectClaimKeys?: string[]
  includedProperties?: CustomPropertyItem[]
  enterprise?: SettingsSource
}

export const organizationOidcConfigurationRoute = actionsOidcConfigurationAppBuilder.createQueryRouteConfig(
  'organizationOidcConfigurationRoute',
  {
    path: '/organizations/:org/settings/actions/oidc-configuration',
    queries: [mainQuery<OrganizationOidcConfigurationResponse>()],
  },
)
